const QUESTIONS = [
  // DOMAIN I
  { id: 1, domain: 'I — Basic Sciences', q: 'Which of the following best describes the Frank-Starling mechanism?', options: ['Cardiac output decreases as ventricular preload increases', 'Stroke volume increases in response to increased ventricular end-diastolic volume', 'Heart rate is the primary determinant of cardiac output', 'Afterload reduction directly increases myocardial contractility'], answer: 1, rationale: 'The Frank-Starling mechanism states that as ventricular filling (preload/EDV) increases, the stretch on myocardial fibers increases, leading to a greater force of contraction and a larger stroke volume. A is incorrect — cardiac output increases with preload up to a point. C is incorrect — while heart rate contributes to CO, the Frank-Starling law specifically concerns stroke volume and preload. D is incorrect — afterload reduction affects wall stress, not the Frank-Starling relationship itself.' },
  { id: 2, domain: 'I — Basic Sciences', q: 'A patient has a PaO2 of 60 mmHg and a PaCO2 of 50 mmHg while breathing room air. What is the most likely cause?', options: ['High-altitude exposure', 'Pulmonary embolism', 'Hypoventilation', 'Diffusion impairment'], answer: 2, rationale: 'The elevated PaCO2 of 50 mmHg indicates CO2 retention, which is only seen with hypoventilation. Using the alveolar gas equation, the expected PaO2 is reduced secondary to the elevated PaCO2, consistent with pure hypoventilation with a normal A-a gradient. High altitude causes hypoxemia with low PaCO2 due to compensatory hyperventilation. PE typically causes hypocapnia. Diffusion impairment causes a widened A-a gradient without CO2 retention.' },
  { id: 3, domain: 'I — Basic Sciences', q: 'Which ion channel is primarily responsible for the rapid depolarization (Phase 0) of a ventricular action potential?', options: ['Voltage-gated potassium channels', 'Slow calcium channels (L-type)', 'Fast sodium channels', 'Hyperpolarization-activated cyclic nucleotide-gated (HCN) channels'], answer: 2, rationale: 'Phase 0 of the ventricular action potential is caused by rapid influx of sodium ions through fast voltage-gated Na+ channels, creating a sharp upstroke. K+ channels open during repolarization (Phase 3). L-type Ca2+ channels are responsible for the plateau phase (Phase 2). HCN channels (funny current) are responsible for spontaneous pacemaker depolarization in SA node cells (Phase 4).' },
  { id: 4, domain: 'I — Basic Sciences', q: 'The oxyhemoglobin dissociation curve shifts to the RIGHT in response to which of the following?', options: ['Decreased PaCO2', 'Decreased temperature', 'Increased 2,3-DPG', 'Alkalosis (increased pH)'], answer: 2, rationale: 'Increased 2,3-DPG decreases hemoglobin\'s affinity for oxygen, shifting the curve right (facilitating O2 unloading to tissues). Decreased PaCO2 causes a left shift. Decreased temperature causes a left shift (increased O2 affinity). Alkalosis (high pH) causes a left shift (Bohr effect).' },
  { id: 5, domain: 'I — Basic Sciences', q: 'Which of the following is the primary site of drug metabolism in the body?', options: ['Kidneys', 'Lungs', 'Liver', 'Small intestine'], answer: 2, rationale: 'The liver is the primary organ for drug metabolism via Phase I (oxidation, reduction, hydrolysis — primarily CYP450 enzymes) and Phase II (conjugation) reactions. The kidneys are the primary organ for drug excretion, not metabolism. The lungs play a minor metabolic role. The small intestine has some first-pass metabolic activity but is secondary to the liver.' },
  { id: 6, domain: 'I — Basic Sciences', q: 'The anatomical dead space in a 70 kg adult is approximately:', options: ['50 mL', '150 mL', '350 mL', '500 mL'], answer: 1, rationale: 'Anatomical dead space represents the conducting airways (trachea, bronchi, bronchioles) that do not participate in gas exchange. It is approximately 1 mL/lb of ideal body weight or about 150 mL in a 70 kg adult. 50 mL is too low. 350 mL is closer to the total tidal volume. 500 mL approximates a normal tidal volume.' },
  { id: 7, domain: 'I — Basic Sciences', q: 'Which neuromuscular junction receptor subtype mediates the depolarizing effect of succinylcholine?', options: ['Muscarinic M2 receptor', 'Nicotinic N1 (ganglionic) receptor', 'Nicotinic N2 (neuromuscular) receptor', 'Alpha-1 adrenergic receptor'], answer: 2, rationale: 'Succinylcholine acts as an agonist at nicotinic N2 (NM) receptors at the neuromuscular junction, causing initial fasciculations followed by sustained depolarization and paralysis. Muscarinic M2 receptors are found in the heart. Nicotinic N1 receptors are located at autonomic ganglia. Alpha-1 adrenergic receptors mediate vasoconstriction and have no role in neuromuscular blockade.' },
  { id: 8, domain: 'I — Basic Sciences', q: 'What is the functional residual capacity (FRC)?', options: ['The maximum volume of air that can be exhaled after a maximum inspiration', 'The volume of air remaining in the lungs after a normal tidal exhalation', 'The maximum volume of air that can be inhaled beyond normal tidal inhalation', 'The minimum volume of air remaining in the lungs after maximal exhalation'], answer: 1, rationale: 'FRC = ERV + RV. It is the volume of air remaining in the lungs at the end of a passive, normal tidal exhalation — the resting position of the respiratory system. A describes vital capacity (VC). C describes inspiratory reserve volume (IRV). D describes residual volume (RV).' },
  { id: 9, domain: 'I — Basic Sciences', q: 'A drug with a high volume of distribution (Vd) would most likely exhibit which characteristic?', options: ['High plasma protein binding', 'Rapid elimination via renal filtration', 'Extensive tissue distribution and sequestration', 'Short duration of action'], answer: 2, rationale: 'A high Vd indicates that the drug distributes extensively into peripheral tissues (fat, muscle) rather than staying in the plasma. High protein binding typically keeps the drug in plasma, resulting in a lower Vd. High Vd usually indicates poor renal clearance. Drugs with high Vd often have a longer duration of action due to slow redistribution back from tissues.' },
  { id: 10, domain: 'I — Basic Sciences', q: 'The Henderson-Hasselbalch equation determines the ratio of ionized to unionized drug. Which form of a WEAK BASE crosses lipid membranes most readily?', options: ['Ionized form (charged)', 'Unionized form (uncharged)', 'Both forms equally', 'Neither form; weak bases require active transport'], answer: 1, rationale: 'For both weak acids and weak bases, it is the unionized (uncharged) form that is lipid-soluble and crosses cell membranes, including the blood-brain barrier and placenta. For a weak base, the unionized form predominates at higher pH (more alkaline environment). The ionized form is water-soluble and cannot readily cross lipid membranes.' },
  { id: 11, domain: 'I — Basic Sciences', q: 'Which of the following correctly describes the renal handling of bicarbonate?', options: ['Bicarbonate is freely filtered and secreted in the collecting duct', 'Bicarbonate is reabsorbed primarily in the proximal tubule', 'Bicarbonate is produced in the loop of Henle', 'Bicarbonate reabsorption is independent of PaCO2'], answer: 1, rationale: 'Approximately 85-90% of filtered bicarbonate is reabsorbed in the proximal tubule via carbonic anhydrase-dependent mechanisms. Bicarbonate is filtered but not secreted; it is reabsorbed. The loop of Henle is primarily involved in sodium and water reabsorption. PaCO2 directly influences bicarbonate reabsorption (high PaCO2 → increased reabsorption).' },
  { id: 12, domain: 'I — Basic Sciences', q: 'Which anesthetic mechanism best describes the action of propofol?', options: ['NMDA receptor antagonism', 'Potentiation of GABA-A receptor chloride currents', 'Alpha-2 adrenergic agonism in the locus coeruleus', 'Opioid receptor agonism'], answer: 1, rationale: 'Propofol primarily acts by positive allosteric modulation of GABA-A receptors, increasing the frequency and duration of chloride channel opening, resulting in neuronal hyperpolarization and CNS depression. NMDA antagonism is the primary mechanism of ketamine. Alpha-2 agonism at the locus coeruleus is the primary mechanism of dexmedetomidine. Opioid receptor agonism is the mechanism of opioids.' },
  { id: 13, domain: 'I — Basic Sciences', q: 'The baroreceptors that regulate blood pressure moment-to-moment are located primarily in the:', options: ['Aortic arch and carotid sinus', 'Renal juxtaglomerular apparatus', 'Hypothalamus and medulla', 'Right atrium and pulmonary artery'], answer: 0, rationale: 'The primary arterial baroreceptors are high-pressure stretch receptors in the aortic arch (afferents via vagus nerve, CN X) and carotid sinus (afferents via glossopharyngeal nerve, CN IX). They provide rapid, beat-to-beat regulation of BP. The juxtaglomerular apparatus senses renal perfusion pressure and regulates renin release (long-term BP control). The hypothalamus and medulla are central processing centers, not the sensors.' },
  { id: 14, domain: 'I — Basic Sciences', q: 'Which of the following laboratory values is most consistent with METABOLIC ALKALOSIS?', options: ['pH 7.28, PaCO2 55 mmHg, HCO3- 22 mEq/L', 'pH 7.52, PaCO2 48 mmHg, HCO3- 38 mEq/L', 'pH 7.32, PaCO2 28 mmHg, HCO3- 14 mEq/L', 'pH 7.48, PaCO2 32 mmHg, HCO3- 24 mEq/L'], answer: 1, rationale: 'pH 7.52 indicates alkalosis. The primary abnormality is elevated HCO3- (38 mEq/L), indicating metabolic alkalosis. The elevated PaCO2 (48 mmHg) represents appropriate respiratory compensation (hypoventilation). A shows acidosis with elevated PaCO2 (primary respiratory acidosis). C shows acidosis with low HCO3- (primary metabolic acidosis). D shows mild alkalosis with low PaCO2 (primary respiratory alkalosis).' },
  { id: 15, domain: 'I — Basic Sciences', q: 'Which of the following correctly describes the concept of context-sensitive half-time?', options: ['The time for plasma drug concentration to fall 50%, which increases with longer infusion duration for many drugs', 'The elimination half-life of a drug regardless of infusion duration', 'The time required for a drug to reach peak effect at the effect site', 'The plasma half-life when the drug is administered by bolus injection'], answer: 0, rationale: 'Context-sensitive half-time (CSHT) refers to the time for plasma drug concentration to decrease by 50% after terminating an infusion, and this value increases with the duration of the infusion ("context") for many drugs (e.g., fentanyl). Drugs like remifentanil have a nearly flat CSHT regardless of infusion duration due to ester hydrolysis. B describes a simple elimination half-life. C describes the effect-site equilibration time (ke0).' },
  { id: 16, domain: 'I — Basic Sciences', q: 'What is the primary pathophysiological mechanism in anaphylaxis?', options: ['IgG-mediated complement activation', 'IgE-mediated mast cell and basophil degranulation', 'Direct T-cell cytotoxicity', 'Type III immune complex deposition'], answer: 1, rationale: 'Anaphylaxis is a Type I (immediate) hypersensitivity reaction. IgE antibodies bound to mast cells and basophils crosslink when the antigen is re-encountered, triggering degranulation and release of histamine, tryptase, prostaglandins, and leukotrienes. IgG-mediated complement activation describes Type II hypersensitivity (cytotoxic). Direct T-cell cytotoxicity is a feature of Type IV (delayed) hypersensitivity. Immune complex deposition describes Type III hypersensitivity.' },
  { id: 17, domain: 'I — Basic Sciences', q: 'Which muscle is the primary muscle of inspiration?', options: ['External intercostals', 'Sternocleidomastoid', 'Diaphragm', 'Scalene muscles'], answer: 2, rationale: 'The diaphragm is responsible for approximately 70-80% of the work of quiet breathing. It contracts and flattens during inspiration, increasing thoracic volume and creating a negative pressure gradient. External intercostals assist inspiration by elevating ribs but are accessory muscles. The sternocleidomastoid is an accessory muscle used during labored breathing. Scalene muscles are also accessory muscles of inspiration.' },
  { id: 18, domain: 'I — Basic Sciences', q: 'The minimum alveolar concentration (MAC) of a volatile anesthetic is DECREASED by which of the following?', options: ['Hyperthermia', 'Chronic alcohol use', 'Hypothermia', 'Hyperthyroidism'], answer: 2, rationale: 'MAC decreases with hypothermia (approximately 5% decrease per degree Celsius below normal), as cold temperatures reduce neuronal metabolic activity and synaptic transmission. Hyperthermia increases MAC (up to 42°C). Chronic alcohol use causes enzyme induction and cross-tolerance, increasing MAC. Hyperthyroidism is associated with increased metabolic rate and increased MAC.' },
  { id: 19, domain: 'I — Basic Sciences', q: 'Which of the following correctly describes the hepatic first-pass effect?', options: ['Intravenous drugs are metabolized by the liver before reaching the systemic circulation', 'Orally administered drugs absorbed from the GI tract pass through the liver before reaching systemic circulation, reducing bioavailability', 'Drugs administered sublingually undergo extensive first-pass metabolism', 'Inhaled anesthetics are primarily metabolized in the first pass through the lungs'], answer: 1, rationale: 'After oral absorption, drugs enter the portal circulation and pass through the liver before reaching systemic circulation. Hepatic metabolism during this first pass can significantly reduce the amount of drug reaching the target organ (e.g., morphine has ~25% oral bioavailability due to first-pass). IV drugs bypass the GI and portal circulation entirely, avoiding first-pass metabolism. Sublingual administration enters the systemic venous circulation directly, bypassing portal and hepatic first-pass metabolism.' },
  { id: 20, domain: 'I — Basic Sciences', q: 'Which coagulation pathway is tested by the prothrombin time (PT/INR)?', options: ['Intrinsic pathway (factors XII, XI, IX, VIII)', 'Extrinsic pathway (factor VII) and common pathway', 'Platelet function and primary hemostasis', 'Fibrinolysis pathway'], answer: 1, rationale: 'PT/INR measures the extrinsic pathway (Factor VII) and the common pathway (Factors X, V, II/prothrombin, and fibrinogen). It is prolonged by warfarin (which inhibits vitamin K-dependent factors II, VII, IX, X). The intrinsic pathway is measured by aPTT. Platelet function is assessed by bleeding time or platelet function assay. Fibrinolysis is assessed by tests such as thromboelastography.' },
  // DOMAIN II
  { id: 21, domain: 'II — Equipment', q: 'During a circle breathing system check, the CRNA notices that the CO2 absorbent has turned a purple/violet color. What does this indicate?', options: ['The absorbent is functioning normally', 'The absorbent is exhausted and must be replaced', 'The absorbent has been exposed to moisture and is reactivating', 'There is a channeling defect in the canister'], answer: 1, rationale: 'Most CO2 absorbents (e.g., soda lime) contain pH indicators. When the absorbent is exhausted (unable to absorb more CO2), the pH drops and the indicator turns from white/pink to a violet/purple color permanently. A functioning absorbent is typically white or very light pink. "Regeneration" of exhausted CO2 absorbent does not restore function sufficiently — it should still be replaced. Channeling causes elevated inspired CO2 but does not cause the color change.' },
  { id: 22, domain: 'II — Equipment', q: 'A patient is connected to a Bain circuit (Mapleson D). What is the minimum fresh gas flow required to prevent rebreathing during SPONTANEOUS ventilation?', options: ['Equal to the patient\'s alveolar minute ventilation', 'Approximately 1-2 L/min', '2-3 times the patient\'s minute ventilation', 'Fresh gas flow is not relevant in the Bain circuit'], answer: 2, rationale: 'The Bain circuit (a coaxial Mapleson D system) requires high fresh gas flows to prevent CO2 rebreathing during spontaneous ventilation — approximately 200-300 mL/kg/min or 2-3 times minute ventilation. During controlled ventilation, lower flows (~70 mL/kg/min) can be used. Matching only alveolar ventilation is insufficient. 1-2 L/min is far too low for an adult patient. Fresh gas flow is critically important in non-rebreathing circuits like the Bain.' },
  { id: 23, domain: 'II — Equipment', q: 'Which type of vaporizer is classified as a variable bypass, agent-specific vaporizer?', options: ['Copper kettle vaporizer', 'Tec series vaporizer (e.g., Tec 7)', 'Desflurane Tec 6 vaporizer', 'Injection vaporizer (e.g., Aladin cassette)'], answer: 1, rationale: 'The Tec series (e.g., Tec 4, 5, 7) are variable bypass, agent-specific, temperature-compensated vaporizers. Gas is split between a bypass chamber and a vaporizing chamber. The copper kettle is a measured-flow vaporizer. The Tec 6 for desflurane is a heated, pressurized vaporizer because desflurane\'s high vapor pressure and low boiling point require a different design. The Aladin cassette used in GE Datex-Ohmeda machines is an injection-type, agent-specific vaporizer.' },
  { id: 24, domain: 'II — Equipment', q: 'What is the purpose of the oxygen flush valve on an anesthesia machine?', options: ['To deliver 100% oxygen directly to the common gas outlet at 35-75 L/min, bypassing flowmeters and vaporizers', 'To fill the oxygen reservoir bag during leak testing', 'To increase the FiO2 delivered through the vaporizer', 'To activate the low oxygen pressure alarm'], answer: 0, rationale: 'The oxygen flush valve delivers 100% oxygen at 35-75 L/min directly to the common gas outlet, bypassing all flowmeters and vaporizers. It is used during emergencies but should be used cautiously — it can cause barotrauma if used during the inspiratory phase and can dilute volatile agents. Filling the reservoir bag is done via fresh gas flow. The flush valve bypasses the vaporizer entirely.' },
  { id: 25, domain: 'II — Equipment', q: 'Which of the following pulse oximetry readings would be MOST inaccurate in a patient with severe carbon monoxide poisoning?', options: ['SpO2 reading of 98%', 'SpO2 reading of 70%', 'SpO2 reading of 50%', 'All readings are equally inaccurate'], answer: 0, rationale: 'Standard pulse oximetry (SpO2) cannot differentiate oxyhemoglobin from carboxyhemoglobin (COHb) because both absorb light at the 660 nm wavelength similarly. In CO poisoning, the oximeter falsely reads COHb as oxyhemoglobin, giving a falsely HIGH and reassuring SpO2 (often 98-100%) even though the patient is severely hypoxic. Co-oximetry (arterial blood gas) is required to detect COHb. A falsely elevated reading is the most clinically dangerous inaccuracy.' },
  { id: 26, domain: 'II — Equipment', q: 'The capnography waveform shows an elevated and gradually rising baseline. What is the most likely cause?', options: ['Esophageal intubation', 'Rebreathing of CO2 due to exhausted absorbent or malfunctioning valve', 'Severe bronchospasm', 'Pulmonary embolism'], answer: 1, rationale: 'An elevated baseline on the capnograph (inspired CO2 >0) with a gradually rising baseline indicates the patient is rebreathing CO2. This occurs when the CO2 absorbent is exhausted, or if an inspiratory or expiratory unidirectional valve is malfunctioning. Esophageal intubation produces a waveform that rapidly disappears. Bronchospasm produces a shark-fin (slanted plateau) waveform but does not elevate the baseline. PE decreases ETCO2 but does not elevate the baseline.' },
  { id: 27, domain: 'II — Equipment', q: 'A correctly positioned endotracheal tube in an adult has its tip located approximately:', options: ['At the carina (T4-T5 level)', '2-3 cm above the carina', 'At the level of the cricoid cartilage', '5-6 cm below the vocal cords'], answer: 1, rationale: 'The tip of the ETT should ideally be 2-3 cm above the carina (approximately at the level of T2 on chest X-ray). This provides an adequate safety margin to prevent right mainstem intubation with neck flexion and to prevent accidental extubation with neck extension. Placement at the carina risks right mainstem intubation with any neck flexion. Placing the tip at the cricoid level would position the ETT cuff at or near the vocal cords, risking laryngeal injury.' },
  { id: 28, domain: 'II — Equipment', q: 'The Laryngeal Mask Airway (LMA) Supreme is best described as:', options: ['A first-generation LMA with a standard bowl-shaped cuff', 'A second-generation supraglottic airway with an integrated bite block, drain tube, and curved rigid airway tube', 'A video laryngoscope used for difficult airways', 'An intubating LMA designed to facilitate blind nasotracheal intubation'], answer: 1, rationale: 'The LMA Supreme is a second-generation supraglottic airway device featuring a pre-curved, rigid airway tube, an elliptical cuff, an integrated bite block, and a drain tube for gastric access/suctioning — reducing aspiration risk compared to first-generation LMAs. First-generation LMAs (Classic, Unique) lack a drain tube. The LMA Supreme is not a video laryngoscope. The LMA Fastrach (Intubating LMA) is designed to facilitate endotracheal intubation.' },
  { id: 29, domain: 'II — Equipment', q: 'Which monitoring standard is considered ESSENTIAL for all anesthetics according to the ASA Standards for Basic Anesthetic Monitoring?', options: ['Arterial line blood pressure', 'Central venous pressure', 'Continuous pulse oximetry', 'Bispectral index (BIS) monitoring'], answer: 2, rationale: 'The ASA Standards for Basic Anesthetic Monitoring require continuous pulse oximetry for all patients receiving anesthesia, along with capnography (when indicated), ECG, blood pressure, and temperature when significant changes are expected. Arterial line is not a basic monitoring standard; it is used selectively. Central venous pressure monitoring is not a basic ASA standard. BIS monitoring is not part of the ASA basic standards, though it may reduce awareness risk.' },
  { id: 30, domain: 'II — Equipment', q: 'The Pin Index Safety System (PISS) is designed to:', options: ['Prevent the attachment of the wrong gas cylinder to the wrong yoke on the anesthesia machine', 'Ensure proper positioning of the endotracheal tube', 'Regulate the pressure of gases delivered to the anesthesia machine', 'Prevent misconnection of IV tubing'], answer: 0, rationale: 'The PISS uses unique pin configurations for each gas type on small E-cylinders, preventing cross-connection (e.g., connecting a CO2 cylinder to an oxygen yoke). Each gas has a specific hole pattern that only accepts that gas\'s cylinder. ETT positioning is confirmed by capnography and clinical assessment. Pressure regulation is the function of the anesthesia machine\'s pressure regulators.' },
  { id: 31, domain: 'II — Equipment', q: 'What is the purpose of the APL (Adjustable Pressure-Limiting) valve?', options: ['To limit the maximum pressure in the breathing circuit during manual or spontaneous ventilation', 'To control the fresh gas flow delivered to the patient', 'To regulate inspired oxygen concentration', 'To activate the high-pressure alarm during mechanical ventilation'], answer: 0, rationale: 'The APL (or "pop-off") valve limits the maximum circuit pressure by venting excess gas to the waste gas scavenging system. It is used during spontaneous and manual (bag) ventilation. During mechanical ventilation it should be closed (or set to maximum) so the ventilator can control pressures. Fresh gas flow is controlled by the flowmeters. FiO2 is controlled by the ratio of O2 to other gases via the flowmeters.' },
  { id: 32, domain: 'II — Equipment', q: 'Which of the following best describes the Doppler ultrasound principle used in TEE/TTE assessment of cardiac output?', options: ['Measurement of myocardial thickness using M-mode', 'Detection of frequency shift in reflected ultrasound waves to measure blood flow velocity', 'Visualization of valve leaflet motion in 2D imaging mode', 'Calculation of ejection fraction from end-systolic and end-diastolic volumes'], answer: 1, rationale: 'Doppler ultrasound detects the frequency shift (Doppler shift) between transmitted and reflected ultrasound waves from moving red blood cells. This shift correlates with blood flow velocity and direction, allowing measurement of transvalvular flow velocities and cardiac output calculations. M-mode imaging measures cardiac dimensions and wall motion over time. 2D imaging uses reflection amplitude to create cross-sectional images. Ejection fraction is calculated geometrically from 2D images using Simpson\'s biplane method.' },
  { id: 33, domain: 'II — Equipment', q: 'During low-flow anesthesia with a volatile agent, compound A formation is a concern. Which absorbent and agent combination most commonly produces Compound A?', options: ['Soda lime + desflurane', 'Baralyme + isoflurane', 'Soda lime or baralyme + sevoflurane', 'Soda lime + nitrous oxide'], answer: 2, rationale: 'Compound A is a nephrotoxic byproduct formed when sevoflurane reacts with CO2 absorbents (especially desiccated soda lime or baralyme) at low fresh gas flows. Concentrations are generally below clinically toxic levels at fresh gas flows ≥2 L/min. Desflurane does not produce Compound A; it produces CO with desiccated absorbents. Isoflurane does not produce Compound A in significant amounts.' },
  { id: 34, domain: 'II — Equipment', q: 'The train-of-four (TOF) ratio is used to assess which of the following?', options: ['Depth of volatile anesthetic', 'Adequacy of neuromuscular blockade reversal', 'Pain response during surgery', 'Level of sedation during monitored anesthesia care'], answer: 1, rationale: 'Train-of-four stimulation delivers 4 successive supramaximal stimuli at 2 Hz. The TOF ratio (T4/T1) reflects the degree of non-depolarizing neuromuscular block. A TOF ratio ≥0.9 (quantitative) is required before extubation to ensure adequate reversal of NMB. Volatile anesthetic depth is assessed by ETAC and BIS. Sedation depth during MAC is assessed by verbal response and BIS/sedation scales.' },
  { id: 35, domain: 'II — Equipment', q: 'A patient develops sudden loss of ETCO2 waveform intraoperatively. What is the FIRST action the CRNA should take?', options: ['Immediately extubate and re-intubate', 'Manually ventilate with 100% oxygen and assess airway patency', 'Increase fresh gas flow', 'Administer epinephrine for suspected cardiac arrest'], answer: 1, rationale: 'Sudden loss of ETCO2 waveform requires immediate manual ventilation with 100% O2 while assessing for the cause: disconnection, esophageal extubation, kinked ETT, severe bronchospasm, massive PE, or cardiac arrest. Manual bag ventilation allows the CRNA to feel compliance, confirm breath sounds, and observe chest rise. Extubation is not the first response. Cardiac arrest is one cause, but it must be confirmed first before giving epinephrine.' },
  { id: 36, domain: 'II — Equipment', q: 'Which IV fluid is considered MOST isotonic to human plasma?', options: ['0.45% Normal Saline (half-normal saline)', '5% Dextrose in Water (D5W)', 'Lactated Ringer\'s solution', '3% Normal Saline'], answer: 2, rationale: 'Lactated Ringer\'s (LR) has an osmolarity of approximately 273 mOsm/L, which is closest to normal plasma (280-295 mOsm/L). It contains Na+, K+, Ca2+, Cl-, and lactate, making it a balanced crystalloid. 0.45% NS is hypotonic (~154 mOsm/L). D5W is effectively hypotonic (~252 mOsm/L initially, but dextrose is rapidly metabolized, leaving free water). 3% NS is hypertonic (~1026 mOsm/L).' },
  { id: 37, domain: 'II — Equipment', q: 'What is the pressure of oxygen in an E-cylinder that is approximately HALF FULL?', options: ['1000 psi', '2200 psi', '750 psi', '500 psi'], answer: 0, rationale: 'Because oxygen is stored as a compressed gas (not a liquid) in E-cylinders, pressure is directly proportional to the volume remaining. A full E-cylinder contains approximately 660 L at ~2200 psi. A half-full cylinder would be at approximately 1100 psi (≈1000 psi is the closest answer). 2200 psi is a full cylinder. 750 psi would represent roughly one-third full. 500 psi represents approximately one-quarter full.' },
  { id: 38, domain: 'II — Equipment', q: 'Which of the following describes the function of the oxygen second-stage pressure regulator on an anesthesia machine?', options: ['It reduces pipeline oxygen pressure from ~50 psi to ~14-16 psi before reaching the flowmeters', 'It increases oxygen pressure for delivery to the oxygen flush valve', 'It reduces high-pressure cylinder oxygen from 2200 psi to ~50 psi', 'It monitors and alarms for low pipeline pressure'], answer: 0, rationale: 'The second-stage pressure regulator reduces the working pressure of oxygen (after the first-stage regulator has already reduced cylinder pressure to ~45 psi, or directly from the 50 psi pipeline) to approximately 14-16 psi before it reaches the flowmeters, ensuring stable, consistent flow. The flush valve operates at pipeline pressure (~50 psi). This function of the first-stage (high-pressure) regulator is to reduce cylinder pressure to ~50 psi.' },
  { id: 39, domain: 'II — Equipment', q: 'Bispectral Index (BIS) monitoring measures which of the following?', options: ['Neuromuscular junction function', 'Processed EEG activity as a surrogate for depth of hypnosis', 'Cerebral blood flow velocity', 'Cerebral oxygenation via near-infrared spectroscopy'], answer: 1, rationale: 'BIS uses a proprietary algorithm to analyze and process raw EEG signals, converting them into a dimensionless number from 0 (isoelectric) to 100 (fully awake). Values of 40-60 are generally targeted for general anesthesia. Neuromuscular junction function is assessed by peripheral nerve stimulator (TOF). Cerebral blood flow velocity is measured by transcranial Doppler. Cerebral oxygenation is measured by cerebral oximetry (NIRS).' },
  { id: 40, domain: 'II — Equipment', q: 'Which of the following correctly describes the Diameter Index Safety System (DISS)?', options: ['A system using pin configurations to prevent wrong-gas connections to E-cylinders', 'A threaded connector system for high-pressure gas hoses and pipeline outlets that prevents misconnection', 'A pressure-relief valve system on the anesthesia gas scavenging system', 'A system used to calibrate oxygen analyzers'], answer: 1, rationale: 'The DISS uses specific diameter and thread configurations for gas-specific connections on pipeline gas outlets and high-flow hoses, preventing cross-connection of different gases. Each gas has a unique diameter/thread combination. The Pin Index Safety System (PISS) uses pin configurations, used for E-cylinders. Pressure-relief valves on the scavenging system are separate safety features.' },
  // DOMAIN III
  { id: 41, domain: 'III — General Principles', q: 'A patient taking monoamine oxidase inhibitors (MAOIs) presents for emergency surgery. Which opioid should be AVOIDED due to risk of a serotonin syndrome or excitatory reaction?', options: ['Morphine', 'Hydromorphone', 'Meperidine (Demerol)', 'Fentanyl'], answer: 2, rationale: 'Meperidine is contraindicated with MAOIs because it inhibits serotonin reuptake, leading to serotonin syndrome (hyperthermia, agitation, clonus, tachycardia, diaphoresis) — potentially fatal. Morphine does not have significant serotonergic activity and is generally considered safer. Hydromorphone lacks serotonergic properties. Fentanyl is generally considered safe with MAOIs as it has minimal serotonergic activity.' },
  { id: 42, domain: 'III — General Principles', q: 'During a rapid sequence induction (RSI), the CRNA applies cricoid pressure (Sellick maneuver). What is the primary purpose of this maneuver?', options: ['To improve laryngoscopic view by displacing the larynx posteriorly', 'To compress the esophagus between the cricoid ring and the cervical vertebra, reducing risk of passive regurgitation', 'To prevent laryngospasm during induction', 'To facilitate nasotracheal intubation'], answer: 1, rationale: 'Cricoid pressure compresses the esophagus between the cricoid cartilage (the only complete tracheal ring) and the posterior cervical vertebrae, which can reduce passive regurgitation of gastric contents. Its effectiveness is debated in the literature and it may worsen laryngoscopic view. BURP (Backward, Upward, Rightward Pressure) is an external laryngeal manipulation maneuver used by the intubating provider. Cricoid pressure is not used to prevent laryngospasm.' },
  { id: 43, domain: 'III — General Principles', q: 'Malignant hyperthermia (MH) is triggered by which anesthetic agents?', options: ['Propofol and ketamine', 'All volatile halogenated agents and succinylcholine', 'Nitrous oxide and opioids', 'Benzodiazepines and neuromuscular blocking agents'], answer: 1, rationale: 'Malignant hyperthermia is triggered by all halogenated volatile anesthetics (sevoflurane, desflurane, isoflurane, halothane) and succinylcholine. These agents cause uncontrolled release of calcium from the sarcoplasmic reticulum via a mutant RYR1 receptor. Propofol is a "safe" TIVA agent used in MH-susceptible patients. Ketamine is also safe. Nitrous oxide, opioids, benzodiazepines, and non-depolarizing NMBs are not MH triggers.' },
  { id: 44, domain: 'III — General Principles', q: 'What is the initial dose of dantrolene for treatment of malignant hyperthermia?', options: ['0.5 mg/kg IV', '2.5 mg/kg IV, repeated every 5 minutes up to 10 mg/kg', '10 mg/kg IV as a single bolus', '1 mg/kg IV, repeated every 10 minutes up to 5 mg/kg'], answer: 1, rationale: 'The initial dose of dantrolene for MH is 2.5 mg/kg IV, repeated every 5 minutes as needed up to a total of 10 mg/kg (or more in severe cases). Dantrolene inhibits calcium release from the sarcoplasmic reticulum by blocking the RYR1 receptor. 0.5 mg/kg is subtherapeutic. 10 mg/kg as a single bolus is not the standard dosing approach. 1 mg/kg every 10 min is not the established protocol.' },
  { id: 45, domain: 'III — General Principles', q: 'A 65-year-old male with a history of CHF (EF 30%) requires anesthesia for a hip replacement. Which induction agent would be MOST appropriate?', options: ['Propofol 2 mg/kg IV rapid bolus', 'Etomidate 0.3 mg/kg IV', 'Ketamine 2 mg/kg IV', 'Thiopental 4 mg/kg IV'], answer: 1, rationale: 'Etomidate is the preferred induction agent for hemodynamically unstable patients or those with severe cardiac dysfunction (low EF) because it provides the greatest cardiovascular stability — it has minimal effects on heart rate, blood pressure, and systemic vascular resistance. Propofol causes significant vasodilation and myocardial depression. Ketamine increases heart rate and blood pressure (sympathomimetic), which can be detrimental in systolic heart failure. Thiopental is a barbiturate that causes significant myocardial depression and hypotension.' },
  { id: 46, domain: 'III — General Principles', q: 'Which of the following is a CONTRAINDICATION to the use of succinylcholine?', options: ['Full stomach and aspiration risk', 'History of malignant hyperthermia susceptibility', 'Pediatric patient under 2 years old', 'Anticipated difficult airway'], answer: 1, rationale: 'Succinylcholine is absolutely contraindicated in patients with known or suspected malignant hyperthermia susceptibility, as it is one of the primary triggers for MH. Full stomach and aspiration risk is actually an indication for RSI where succinylcholine is frequently used. Pediatric patients can receive succinylcholine, though its use in children requires extra caution. Anticipated difficult airway is a relative consideration but not an absolute contraindication.' },
  { id: 47, domain: 'III — General Principles', q: 'Neostigmine reversal of non-depolarizing neuromuscular blockade works by:', options: ['Directly competing with the blocking agent at the nicotinic receptor', 'Inhibiting acetylcholinesterase, increasing acetylcholine at the NMJ to compete with the blocking agent', 'Chelating the blocking agent and removing it from the receptor', 'Stimulating the NMJ directly via a separate receptor mechanism'], answer: 1, rationale: 'Neostigmine is an acetylcholinesterase inhibitor. By inhibiting the breakdown of acetylcholine, it increases ACh concentration at the NMJ, which competes with non-depolarizing NMBAs for the nicotinic receptor, reversing blockade. An anticholinergic (glycopyrrolate or atropine) must be co-administered to prevent muscarinic side effects. Neostigmine does not directly compete at the nicotinic receptor. Chelation/encapsulation is the mechanism of sugammadex.' },
  { id: 48, domain: 'III — General Principles', q: 'A patient develops ST-segment depression in leads II and V5 during anesthetic. What is the most appropriate initial intervention?', options: ['Administer atropine 0.5 mg IV', 'Increase the FiO2 to 100% and optimize hemodynamics (BP, HR)', 'Immediately terminate the procedure', 'Administer adenosine 6 mg IV'], answer: 1, rationale: 'ST-segment depression indicates myocardial ischemia. The first step is to optimize oxygen delivery: increase FiO2 to 100%, maintain adequate blood pressure (treat hypotension), and optimize heart rate (treat tachycardia or bradycardia). Notify the surgeon and consider nitroglycerin or other interventions based on cause. Atropine is used for symptomatic bradycardia, not ST depression. Adenosine is used for SVT, not ischemia.' },
  { id: 49, domain: 'III — General Principles', q: 'Which positioning complication is most commonly associated with the lithotomy position?', options: ['Brachial plexus injury', 'Compartment syndrome of the lower extremities', 'Air embolism', 'Radial nerve palsy'], answer: 1, rationale: 'Compartment syndrome of the lower legs is a well-recognized complication of lithotomy position, especially with long duration procedures. Elevated limb position reduces arterial perfusion pressure while venous compression increases compartment pressure. Brachial plexus injury is more commonly associated with lateral or extended arm positions. Air embolism risk is highest in the sitting position. Radial nerve palsy is associated with arm positioning on poorly padded arm boards.' },
  { id: 50, domain: 'III — General Principles', q: 'The MAC-awake value (the concentration at which 50% of patients open their eyes on command) is approximately what fraction of MAC?', options: ['1.3 MAC', '1.0 MAC', '0.5 MAC', '0.3 MAC'], answer: 3, rationale: 'MAC-awake is approximately 0.3-0.4 MAC (roughly one-third of the MAC for unconsciousness). This is the concentration below which patients will regain awareness and response to verbal commands — critical when planning emergence. 1.3 MAC is approximately MAC-intubation. 1.0 MAC prevents movement in 50% of patients in response to a skin incision. 0.5 MAC represents half the MAC for surgical stimulation, not MAC-awake.' },
  { id: 51, domain: 'III — General Principles', q: 'Which of the following best describes the Bezold-Jarisch reflex?', options: ['Paradoxical bradycardia and vasodilation in response to a hypovolemic, underfilled ventricle', 'Reflex tachycardia in response to hemorrhage', 'Coronary vasospasm triggered by aortic cross-clamping', 'Pulmonary vasoconstriction in response to hypoxia'], answer: 0, rationale: 'The Bezold-Jarisch reflex is a cardioinhibitory reflex triggered by stimulation of ventricular mechanoreceptors (C-fibers) in an underfilled, vigorously contracting heart (e.g., during spinal anesthesia with hypovolemia or during robotic surgery in steep Trendelenburg). It causes sudden bradycardia, hypotension, and vasodilation — potentially resulting in cardiac arrest. Reflex tachycardia in response to hemorrhage is part of the baroreflex response. Hypoxic pulmonary vasoconstriction (HPV) is a separate reflex.' },
  { id: 52, domain: 'III — General Principles', q: 'Which of the following is the MOST reliable sign of adequate reversal of neuromuscular blockade before extubation?', options: ['Ability to lift the head for 5 seconds', 'TOF ratio ≥0.9 by quantitative acceleromyography', 'Return of spontaneous tidal volume >200 mL', 'Presence of 4 twitches on TOF by tactile assessment'], answer: 1, rationale: 'Quantitative TOF ratio ≥0.9 (measured by acceleromyography or mechanomyography) is the most reliable objective criterion for adequate reversal of neuromuscular blockade. The 5-second head lift is a clinical test but is insensitive; patients can perform it at TOF ratios as low as 0.5-0.6. Tidal volume recovery does not reliably indicate complete reversal. Tactile (qualitative) assessment of 4 twitches on TOF is unreliable because fade may not be detected until TOF ratio is <0.4.' },
  { id: 53, domain: 'III — General Principles', q: 'Which local anesthetic has the LONGEST duration of action?', options: ['Lidocaine', 'Mepivacaine', 'Chloroprocaine', 'Bupivacaine'], answer: 3, rationale: 'Bupivacaine is an amide local anesthetic with the highest protein binding (~95%) and highest lipid solubility among the choices, resulting in the longest duration of action (3-10 hours depending on route). Lidocaine has a moderate duration (1-3 hours). Mepivacaine has a moderate duration (1.5-3 hours). Chloroprocaine is an ester local anesthetic with the shortest duration of action due to rapid hydrolysis by plasma pseudocholinesterase.' },
  { id: 54, domain: 'III — General Principles', q: 'A patient under general anesthesia develops sudden-onset hypotension, hypoxemia, bronchospasm, and urticaria. What is the FIRST-LINE treatment?', options: ['Diphenhydramine 50 mg IV and methylprednisolone 125 mg IV', 'Epinephrine 0.3 mg IM (anterolateral thigh) or IV per weight', 'Norepinephrine infusion at 0.1 mcg/kg/min', 'Albuterol 2.5 mg nebulized'], answer: 1, rationale: 'Epinephrine is the first-line treatment for anaphylaxis. Its alpha-1 effects reverse vasodilation and angioedema; its beta-2 effects reverse bronchospasm; and its beta-1 effects increase cardiac output. Under GA, IV epinephrine is typically given in small incremental doses (10-100 mcg IV boluses). Antihistamines and steroids are secondary treatments; they do not address the acute life-threatening symptoms rapidly enough. Albuterol targets only the bronchospasm component.' },
  { id: 55, domain: 'III — General Principles', q: 'Which of the following describes the effect of nitrous oxide (N2O) on closed gas-filled spaces?', options: ['N2O shrinks gas-filled spaces by binding to nitrogen', 'N2O diffuses into closed gas-filled spaces faster than nitrogen diffuses out, causing them to expand', 'N2O has no effect on closed gas-filled spaces at standard concentrations', 'N2O reduces surface tension in gas-filled spaces, compressing them'], answer: 1, rationale: 'N2O is 34 times more soluble in blood than nitrogen. It diffuses into closed gas-filled spaces (pneumothorax, bowel, middle ear, pneumocephalus, air embolism, ETT cuff) faster than nitrogen can diffuse out, causing these spaces to expand in volume and/or pressure. N2O should be avoided when these spaces exist. N2O does not bind nitrogen and has no direct effect on surface tension in this context.' },
  { id: 56, domain: 'III — General Principles', q: 'A patient is receiving a continuous remifentanil infusion. Compared to fentanyl, remifentanil\'s most unique pharmacokinetic property is:', options: ['High protein binding causing prolonged effect', 'Metabolism by plasma and tissue esterases resulting in a short, predictable offset', 'Primarily hepatic metabolism via CYP3A4', 'Renal elimination making dose reduction necessary in renal failure'], answer: 1, rationale: 'Remifentanil contains an ester linkage and is metabolized by non-specific blood and tissue esterases (NOT plasma cholinesterase/pseudocholinesterase) to inactive metabolites. This gives it an ultra-short, predictable offset regardless of infusion duration (context-sensitive half-time ~3-4 min), making it ideal for procedures requiring rapid emergence. Remifentanil is not a substrate for CYP3A4. Renal failure does not significantly affect remifentanil\'s duration because its inactive metabolite has no opioid activity.' },
  { id: 57, domain: 'III — General Principles', q: 'The Mallampati classification is used to predict:', options: ['Risk of aspiration during induction', 'Difficulty of mask ventilation', 'Likely difficulty of direct laryngoscopy and intubation based on pharyngeal view', 'Risk of postoperative nausea and vomiting'], answer: 2, rationale: 'The Mallampati score (Class I-IV) evaluates the visible pharyngeal structures with the mouth open and tongue out. Class III-IV correlates with reduced visibility of the glottis and predicted difficult laryngoscopy. Aspiration risk is evaluated by NPO status, gastric emptying history, and LES competence. Mask ventilation difficulty predictors include obesity, beard, edentulous state, and OSA. PONV risk is assessed by the Apfel score.' },
  { id: 58, domain: 'III — General Principles', q: 'Which of the following MOST accurately describes the effect of increasing intraabdominal pressure during laparoscopy on cardiac output?', options: ['CO consistently increases due to autotransfusion from abdominal compression', 'CO may decrease due to venous compression reducing preload, combined with increased afterload from elevated SVR', 'CO is unaffected by pneumoperitoneum', 'CO always increases because CO2 stimulates the sympathetic nervous system'], answer: 1, rationale: 'During pneumoperitoneum, elevated IAP (typically 12-15 mmHg) compresses the inferior vena cava and reduces venous return (preload), while also increasing SVR (afterload). The net effect on CO depends on the patient\'s cardiac status — CO may decrease, especially in patients with poor cardiac reserve. While abdominal compression initially may increase venous return, the sustained IVC compression dominates. CO2 absorption during laparoscopy stimulates the SNS but the net effect on CO is still often negative.' },
  { id: 59, domain: 'III — General Principles', q: 'What is the significance of a "cannot intubate, cannot oxygenate" (CICO) scenario?', options: ['It indicates the need for an awake fiberoptic intubation', 'It is a life-threatening emergency requiring immediate front-of-neck access (cricothyrotomy)', 'It mandates conversion to total intravenous anesthesia', 'It can be managed by inserting a larger-bore oropharyngeal airway'], answer: 1, rationale: 'CICO (also called "cannot intubate, cannot ventilate" or CICV) is a life-threatening emergency where the patient cannot be intubated AND mask/supraglottic ventilation is also failing. This situation demands immediate front-of-neck access (emergency cricothyrotomy or surgical airway) to establish oxygenation. Awake fiberoptic intubation is a technique to avoid predicted difficult airway situations, not a rescue in CICO. TIVA does not address the airway emergency.' },
  { id: 60, domain: 'III — General Principles', q: 'Which of the following is a hallmark sign of LOCAL ANESTHETIC SYSTEMIC TOXICITY (LAST)?', options: ['Hypertension and bradycardia', 'Progressive CNS symptoms (tinnitus, perioral numbness, seizures) followed by cardiovascular collapse', 'Hyperthermia and muscle rigidity', 'Rash and urticaria'], answer: 1, rationale: 'LAST classically presents in a biphasic pattern: initial CNS excitation (tinnitus, metallic taste, perioral numbness, visual changes, agitation, seizures) followed by CNS depression and then cardiovascular toxicity (arrhythmias, wide QRS, cardiovascular collapse). Bupivacaine is most cardiotoxic. Treatment includes stopping the LA, airway management, lipid emulsion (Intralipid 20%), and ACLS. Hyperthermia and rigidity describe malignant hyperthermia. Rash/urticaria describe allergic reactions.' },
  { id: 61, domain: 'III — General Principles', q: 'Which of the following is the recommended treatment for LAST (Local Anesthetic Systemic Toxicity) in addition to standard ACLS?', options: ['Sodium bicarbonate infusion', '20% Lipid Emulsion (Intralipid)', 'Physostigmine', 'Dantrolene'], answer: 1, rationale: 'Intravenous 20% lipid emulsion (ILE) is the specific antidote for LAST. It acts as a "lipid sink," binding free lipid-soluble local anesthetic in the plasma and removing it from cardiac tissue. Bolus 1.5 mL/kg followed by infusion at 0.25 mL/kg/min. Sodium bicarbonate may help with hyperkalemia or wide-complex tachycardias but is not the primary treatment for LAST. Physostigmine reverses anticholinergic toxicity. Dantrolene is the treatment for malignant hyperthermia.' },
  { id: 62, domain: 'III — General Principles', q: 'Which of the following is the MOST important predictor of postoperative nausea and vomiting (PONV) according to the Apfel Score?', options: ['History of diabetes mellitus', 'Female sex', 'Use of volatile anesthetics', 'Duration of surgery >3 hours'], answer: 1, rationale: 'The four Apfel risk factors for PONV are: (1) Female sex, (2) Non-smoker, (3) History of PONV or motion sickness, (4) Postoperative opioid use. Each factor adds ~20% risk. Female sex is one of the most heavily weighted individual factors. Diabetes is not an Apfel score factor. Volatile anesthetics increase PONV but are not part of the standard 4-factor Apfel score. Duration of surgery is not included in the original Apfel score.' },
  { id: 63, domain: 'III — General Principles', q: 'What is the mechanism of action of ondansetron (Zofran) for PONV prophylaxis?', options: ['Dopamine (D2) receptor antagonism at the chemoreceptor trigger zone', '5-HT3 receptor antagonism in the GI tract and CNS', 'Histamine H1 receptor antagonism', 'Anticholinergic action reducing GI motility'], answer: 1, rationale: 'Ondansetron is a selective 5-HT3 (serotonin) receptor antagonist. It blocks serotonin receptors in the vagal afferents of the GI tract and in the chemoreceptor trigger zone (CTZ), reducing the emetic signal. D2 receptor antagonism is the mechanism of droperidol, metoclopramide, and promethazine. H1 antihistamines (diphenhydramine, promethazine) have antiemetic properties but via a different mechanism. Anticholinergics (scopolamine) reduce PONV via different receptors.' },
  { id: 64, domain: 'III — General Principles', q: 'A patient\'s blood pressure drops to 70/40 mmHg immediately after spinal anesthesia for a C-section. What is the FIRST-LINE vasopressor of choice?', options: ['Ephedrine 50 mg IV bolus', 'Phenylephrine 100 mcg IV or infusion', 'Vasopressin 20 units IV', 'Dopamine infusion at 10 mcg/kg/min'], answer: 1, rationale: 'Phenylephrine is the current first-line vasopressor for spinal hypotension during cesarean delivery per SOAP and ASA guidelines. Its pure alpha-1 agonism restores SVR without increasing heart rate, and studies show it better maintains fetal acid-base status compared to ephedrine. Ephedrine is now second-line (or used for bradycardia with hypotension) because its beta-agonist properties can cause fetal acidosis via increased fetal metabolism. Vasopressin is not first-line for obstetric spinal hypotension.' },
  { id: 65, domain: 'III — General Principles', q: 'During a thoracic procedure requiring one-lung ventilation (OLV), which physiological change is EXPECTED?', options: ['PaO2 increases due to improved ventilation-perfusion matching', 'Increased shunt fraction through the non-ventilated lung causing hypoxemia', 'PaCO2 decreases due to increased alveolar ventilation', 'Pulmonary vascular resistance decreases in the operative lung'], answer: 1, rationale: 'During OLV, the non-ventilated lung continues to be perfused (surgical side), creating a true intrapulmonary shunt (perfusion without ventilation). This obligatory shunt fraction causes hypoxemia. Hypoxic pulmonary vasoconstriction (HPV) in the non-ventilated lung helps reduce (but does not eliminate) this shunt. OLV worsens V/Q matching. PaCO2 may rise during OLV due to increased dead space. PVR increases in the non-ventilated lung via HPV (not decreases).' },
  { id: 66, domain: 'III — General Principles', q: 'Which of the following is a clinical feature of HIGH SPINAL ANESTHESIA?', options: ['Hypertension and bradycardia', 'Hypertension with tachycardia', 'Hypotension, bradycardia, and respiratory compromise', 'Hypotension with reflex tachycardia only'], answer: 2, rationale: 'High spinal anesthesia (block ascending to T1-T4) causes: hypotension (sympathetic blockade → vasodilation), bradycardia (block of cardiac accelerator fibers T1-T4), and respiratory compromise (paralysis of intercostal and potentially phrenic nerve [C3-C5] innervation to the diaphragm). Hypertension is not expected with high spinal. Tachycardia would not occur if the cardiac accelerator fibers are blocked.' },
  { id: 67, domain: 'III — General Principles', q: 'Volatile anesthetic agents decrease systemic vascular resistance (SVR). Which agent causes the GREATEST decrease in SVR?', options: ['Isoflurane', 'Sevoflurane', 'Desflurane', 'Halothane'], answer: 0, rationale: 'Among modern volatile agents, isoflurane is associated with the greatest reduction in SVR (vasodilation), which often maintains or increases heart rate as a compensatory mechanism. Sevoflurane causes less vasodilation than isoflurane. Desflurane also causes SVR reduction but is notable for its sympathomimetic effects when concentrations are increased rapidly. Halothane causes less vasodilation and more myocardial depression than isoflurane.' },
  { id: 68, domain: 'III — General Principles', q: 'An epidural catheter is being tested with a test dose of lidocaine with epinephrine (3 mL of 1.5% lidocaine + 1:200,000 epinephrine). An INTRAVASCULAR injection would be indicated by:', options: ['Decrease in heart rate of 20 bpm', 'Increase in heart rate of 20 bpm or more and blood pressure increase', 'Rapid onset of complete motor block in the legs', 'Onset of sensory block to T10 within 5 minutes'], answer: 1, rationale: 'The epinephrine component (15 mcg) of the epidural test dose serves as a marker for intravascular injection. IV epinephrine causes a rapid increase in heart rate ≥20 bpm (within 20-60 seconds) and blood pressure increase. Bradycardia is not a sign of intravascular epinephrine injection. Rapid onset of motor block suggests subarachnoid (intrathecal) injection of the local anesthetic, not intravascular. A sensory block to T10 also suggests possible intrathecal placement.' },
  { id: 69, domain: 'III — General Principles', q: 'Which of the following is the PRIMARY anesthetic consideration for a patient with severe aortic stenosis (AS)?', options: ['Maintain elevated heart rate to increase cardiac output', 'Maintain sinus rhythm, avoid tachycardia, and maintain systemic vascular resistance', 'Aggressively reduce preload to decrease wall stress', 'Allow moderate hypotension as the fixed obstruction limits cardiac output anyway'], answer: 1, rationale: 'In severe AS, the left ventricle is pressure-overloaded and hypertrophied. Key goals: maintain sinus rhythm (atrial kick contributes significantly to filling); avoid tachycardia (reduces diastolic filling time); maintain SVR (hypotension rapidly causes ischemia); and maintain adequate preload. Tachycardia is dangerous in AS. Reducing preload is dangerous; the hypertrophied LV is preload-dependent. Hypotension must be avoided as it causes coronary ischemia.' },
  { id: 70, domain: 'III — General Principles', q: 'The addition of epinephrine to a local anesthetic solution for peripheral nerve block serves which primary purpose?', options: ['Increases the pH to speed onset of the local anesthetic', 'Causes vasoconstriction, reducing systemic absorption and prolonging block duration', 'Acts as a co-analgesic by binding alpha-2 receptors', 'Prevents neurotoxicity of the local anesthetic'], answer: 1, rationale: 'Epinephrine (typically 1:200,000 or 5 mcg/mL) causes local vasoconstriction via alpha-1 receptors. This reduces vascular uptake (systemic absorption) of the local anesthetic, prolongs its duration of action at the nerve, and can also serve as a marker for intravascular injection. Sodium bicarbonate (not epinephrine) is added to increase pH and speed onset. Alpha-2 agonist co-analgesic effect describes clonidine or dexmedetomidine. Epinephrine does not prevent neurotoxicity.' },
  { id: 71, domain: 'III — General Principles', q: 'Which of the following correctly describes the effect of VOLATILE ANESTHETICS on the electroencephalogram (EEG)?', options: ['Low doses increase EEG frequency (high-frequency activity), while high doses produce burst suppression or isoelectric pattern', 'Volatile agents have no effect on the EEG', 'Volatile agents consistently produce theta-wave predominance at all doses', 'High doses of volatile anesthetics produce seizure activity on EEG'], answer: 0, rationale: 'At low/sub-anesthetic doses, volatile agents initially increase beta activity. As concentration increases, EEG shifts through alpha and delta waves (slowing), eventually producing burst suppression at high doses, and at very high concentrations, an isoelectric (flat) EEG. Volatile agents have well-documented dose-dependent EEG effects. Theta waves are not the characteristic pattern at all doses. While enflurane (now obsolete) could cause epileptiform activity, modern agents generally cause EEG slowing, not seizures.' },
  { id: 72, domain: 'III — General Principles', q: 'What is the primary pharmacological mechanism of dexmedetomidine?', options: ['GABA-A receptor potentiation', 'Selective alpha-2 adrenergic receptor agonism in the locus coeruleus', 'Opioid mu receptor agonism', 'NMDA receptor antagonism'], answer: 1, rationale: 'Dexmedetomidine is a highly selective alpha-2 adrenergic agonist (alpha-2 to alpha-1 selectivity ratio of 1600:1). Its sedative, analgesic, and anxiolytic effects are primarily mediated by agonism at alpha-2 receptors in the locus coeruleus, decreasing norepinephrine release and mimicking natural sleep pathways. GABA-A potentiation is the mechanism of propofol, benzodiazepines, and barbiturates. NMDA antagonism is the mechanism of ketamine.' },
  { id: 73, domain: 'III — General Principles', q: 'For a patient scheduled for outpatient surgery who takes aspirin 81 mg daily, what is the MOST appropriate management regarding aspirin prior to the procedure?', options: ['Aspirin must be discontinued at least 10 days before all surgeries', 'Continue aspirin perioperatively for patients on aspirin for secondary cardiovascular prevention', 'Always discontinue aspirin 7 days prior to any elective procedure', 'Aspirin has no effect on platelet function and need not be considered'], answer: 1, rationale: 'For patients taking low-dose aspirin for secondary cardiovascular prevention (e.g., prior MI, stent), current guidelines generally recommend continuing aspirin perioperatively because the risk of thrombotic events outweighs the modest increased bleeding risk. Exceptions include procedures with high bleeding risk (intracranial, spinal surgery). While aspirin irreversibly inhibits platelets for their lifespan (~10 days), routine discontinuation is not required for all surgeries.' },
  { id: 74, domain: 'III — General Principles', q: 'The most common cause of hypoxemia in the early postoperative period is:', options: ['Pulmonary embolism', 'Tension pneumothorax', 'Atelectasis and hypoventilation', 'Pulmonary edema'], answer: 2, rationale: 'Atelectasis (from loss of FRC, diaphragmatic dysfunction, pain splinting, and supine positioning) and hypoventilation (from residual anesthetics, opioids, and neuromuscular blocking agents) are the most common causes of early postoperative hypoxemia. PE is a less common but serious cause. Tension pneumothorax is an emergency but not the most common cause. Pulmonary edema can occur but is less common than atelectasis/hypoventilation.' },
  { id: 75, domain: 'III — General Principles', q: 'Which of the following clinical signs is MOST consistent with laryngospasm?', options: ['Stridor with high-pitched inspiratory noise and paradoxical chest/abdominal movement', 'Low-pitched expiratory wheeze with prolonged expiration', 'Complete absence of all breath sounds bilaterally with equal chest rise', 'Gradual onset of desaturation with a normal respiratory pattern'], answer: 0, rationale: 'Laryngospasm occurs when the vocal cords forcefully adduct, partially or completely obstructing the airway. Signs include high-pitched crowing/stridor (partial), paradoxical chest-abdominal movement (rocking), and marked use of accessory muscles. Complete laryngospasm produces total obstruction (no sound) with inability to ventilate. Low-pitched expiratory wheeze with prolonged expiration is characteristic of bronchospasm. Gradual desaturation with normal breathing pattern suggests hypoventilation or atelectasis.' },
  // DOMAIN IV
  { id: 76, domain: 'IV — Surgical & Special Populations', q: 'A term neonate (38 weeks) presents for repair of a tracheoesophageal fistula (TEF). What is a critical anesthetic consideration for this procedure?', options: ['Avoid controlled ventilation until after chest is opened', 'Awake intubation with careful ETT positioning distal to the fistula; avoid high airway pressures', 'Rapid sequence induction with propofol and succinylcholine', 'Place a double-lumen tube for one-lung ventilation'], answer: 1, rationale: 'In TEF, positive pressure ventilation can force gas through the fistula into the stomach, causing massive gastric distension and compromised diaphragmatic excursion. Awake or semi-awake intubation with careful positioning of the ETT distal to the fistula, minimizing airway pressures, is key. Spontaneous ventilation before fistula ligation is preferred when possible. RSI with propofol and succinylcholine is not appropriate for a neonate with TEF. Double-lumen tubes are not used in neonates.' },
  { id: 77, domain: 'IV — Surgical & Special Populations', q: 'A morbidly obese patient (BMI 52) presents for laparoscopic sleeve gastrectomy. Which anesthetic modification is MOST important?', options: ['Use a laryngeal mask airway to avoid the difficulty of endotracheal intubation', 'Preoxygenate in the ramped/head-up position using high-flow oxygen; anticipate rapid desaturation', 'Administer propofol based on total body weight', 'Avoid neuromuscular blockade to prevent postoperative respiratory complications'], answer: 1, rationale: 'Morbidly obese patients have significantly reduced FRC and rapid O2 consumption, leading to precipitous desaturation during apnea. Preoxygenation in the 25-30° head-up (ramped) position maximizes FRC and extends safe apnea time. LMA is relatively contraindicated in morbidly obese patients due to high aspiration risk. Propofol for obese patients should be based on lean body weight (LBW), not total body weight, to avoid overdose. Adequate neuromuscular blockade improves intubating conditions and surgical exposure.' },
  { id: 78, domain: 'IV — Surgical & Special Populations', q: 'Which of the following is the MOST common cardiac arrhythmia in a patient following coronary artery bypass grafting (CABG)?', options: ['Ventricular tachycardia', 'Complete heart block', 'Atrial fibrillation', 'Sinus bradycardia'], answer: 2, rationale: 'Atrial fibrillation (AF) is the most common arrhythmia following CABG, occurring in 20-40% of patients. It typically occurs 2-4 days postoperatively and is associated with increased length of stay, stroke risk, and hemodynamic compromise. Prophylactic beta-blockers and amiodarone are used for prevention. Ventricular tachycardia can occur but is less common. Complete heart block is uncommon unless there is AV node involvement during surgery.' },
  { id: 79, domain: 'IV — Surgical & Special Populations', q: 'An infant with pyloric stenosis presents for pyloromyotomy. The preoperative blood gas shows pH 7.56, PaCO2 48 mmHg, HCO3- 42 mEq/L. What is the metabolic derangement, and when is surgery safe?', options: ['Metabolic acidosis; surgery can proceed immediately', 'Metabolic alkalosis; surgery should be delayed until electrolytes are corrected (Cl-, K+, Na+)', 'Respiratory alkalosis; surgery can proceed after hyperventilation is corrected', 'Normal values for an infant; surgery can proceed'], answer: 1, rationale: 'Pyloric stenosis causes a hypochloremic, hypokalemic metabolic alkalosis from repeated vomiting of gastric (HCl-rich) contents. The alkalosis must be corrected with IV fluids (0.9% NS with KCl supplementation) before surgery. Pyloric stenosis is an urgent but NOT emergent surgical condition — proceeding with an uncorrected alkalosis risks respiratory depression and apnea postoperatively as the body attempts to compensate. The elevated HCO3- and low Cl-/K+ confirm metabolic alkalosis with respiratory compensation.' },
  { id: 80, domain: 'IV — Surgical & Special Populations', q: 'What is the PRIMARY concern when anesthetizing a patient with a large anterior mediastinal mass for biopsy?', options: ['Risk of air embolism during dissection', 'Risk of complete airway collapse and cardiovascular compression upon induction of general anesthesia', 'High probability of esophageal compression causing aspiration', 'Increased risk of pleural effusion after induction'], answer: 1, rationale: 'Anterior mediastinal masses can compress the trachea, bronchi, and great vessels. Loss of spontaneous ventilation and chest muscle tone during GA can cause complete tracheal/bronchial collapse and/or SVC compression, resulting in an unventilatable, hemodynamically unstable situation. Awake fiberoptic intubation in the sitting position, maintaining spontaneous ventilation until the airway is secured, is the safest strategy. Air embolism is not the primary concern for this anatomy.' },
  { id: 81, domain: 'IV — Surgical & Special Populations', q: 'A parturient in labor requests a combined spinal-epidural (CSE). The intrathecal component typically includes which combination?', options: ['High-dose epidural local anesthetic with steroid', 'Low-dose intrathecal opioid (fentanyl) with or without small-dose local anesthetic (bupivacaine)', 'Epinephrine with normal saline for a test dose', 'Ketamine and midazolam for sedation'], answer: 1, rationale: 'The CSE technique for labor analgesia typically combines a low-dose intrathecal injection (e.g., fentanyl 10-25 mcg ± bupivacaine 1.25-2.5 mg) for rapid onset of analgesia, followed by epidural catheter placement for ongoing labor pain management. High-dose local anesthetics are for surgical anesthesia (C-section), not labor analgesia. Describing the epidural test dose, not the intrathecal component. Ketamine and midazolam are IV sedatives not used intrathecally.' },
  { id: 82, domain: 'IV — Surgical & Special Populations', q: 'Patients with renal failure presenting for surgery have which coagulation abnormality that is most clinically significant?', options: ['Thrombocytopenia (low platelet count)', 'Platelet dysfunction (uremic platelet dysfunction) despite a normal platelet count', 'Elevated INR due to decreased clotting factor production', 'Hypercoagulability due to elevated fibrinogen'], answer: 1, rationale: 'Uremia impairs platelet function (aggregation and adhesion) due to accumulation of uremic toxins (guanidinosuccinic acid, phenolic compounds) that interfere with platelet-vessel wall interaction and vWF binding. The platelet count is usually normal, but bleeding time is prolonged. Treatment options include DDAVP (desmopressin), cryoprecipitate, dialysis, and estrogen. Thrombocytopenia is not the primary coagulation issue in CKD. Clotting factor synthesis is primarily a liver function.' },
  { id: 83, domain: 'IV — Surgical & Special Populations', q: 'A pediatric patient (age 3) requires adenotonsillectomy. What is an important postoperative concern specific to this procedure?', options: ['Hyperkalemia from blood transfusion', 'Post-obstructive pulmonary edema and risk of respiratory compromise in children with severe OSA', 'Hypothermia from prolonged operating time', 'Delayed emergence due to NMDA receptor immaturity'], answer: 1, rationale: 'Children with obstructive sleep apnea (OSA) — a primary indication for adenotonsillectomy — are at increased risk for post-obstructive pulmonary edema, respiratory depression (heightened opioid sensitivity), and airway obstruction in the recovery period. These children may require a period of observation or even overnight monitoring. Hyperkalemia from transfusion is a concern in massive transfusion, not routine tonsillectomy. While hypothermia is a general pediatric concern, it is not specific to this procedure.' },
  { id: 84, domain: 'IV — Surgical & Special Populations', q: 'During a transurethral resection of the prostate (TURP), the patient develops confusion, nausea, and visual disturbances. What syndrome is most likely?', options: ['Malignant hyperthermia', 'TURP syndrome (hyponatremia from absorption of hypotonic irrigating fluid)', 'Allergic reaction to the irrigating solution', 'Air embolism from the irrigation system'], answer: 1, rationale: 'TURP syndrome results from absorption of large volumes of hypotonic irrigating fluid (e.g., glycine, sorbitol) through open prostatic venous sinuses, causing dilutional hyponatremia, fluid overload, and neurological symptoms (confusion, visual changes, nausea) due to cerebral edema. Treatment: stop procedure, furosemide, hypertonic saline (3%) for severe hyponatremia. MH is triggered by volatile agents and succinylcholine; it presents with hyperthermia and rigidity. Air embolism presents with ETCO2 drop, "mill wheel" murmur, and cardiovascular collapse.' },
  { id: 85, domain: 'IV — Surgical & Special Populations', q: 'What is the most appropriate anesthetic management for a patient with INCREASED INTRACRANIAL PRESSURE (ICP) undergoing craniotomy?', options: ['Use of ketamine as the primary induction agent', 'Controlled hyperventilation to PaCO2 35-40 mmHg, head-up positioning, and avoid agents that increase ICP', 'Maintain PaCO2 at 55 mmHg to maximize cerebral blood flow', 'Use of 100% N2O to maintain anesthesia and minimize volatile agent use'], answer: 1, rationale: 'ICP management during craniotomy includes: head-up 15-30° (promotes venous drainage), controlled mild hyperventilation to PaCO2 35-40 mmHg (acute reduction causes cerebral vasoconstriction), mannitol or hypertonic saline for brain relaxation, and avoiding agents that increase ICP (ketamine, high-dose volatile agents). Ketamine is traditionally avoided in elevated ICP because it increases cerebral blood flow, CMRO2, and ICP. PaCO2 55 mmHg (hypoventilation) causes cerebral vasodilation and increases ICP. N2O increases cerebral blood flow and CMRO2.' },
  { id: 86, domain: 'IV — Surgical & Special Populations', q: 'A patient with a known pheochromocytoma is scheduled for adrenalectomy. What is the MOST important preoperative preparation?', options: ['Aggressive fluid restriction to prevent perioperative hypertension', 'Alpha-adrenergic blockade (phenoxybenzamine) for 10-14 days followed by beta-blockade', 'Beta-blockade alone to prevent tachycardia', 'Administration of clonidine for 1 week preoperatively'], answer: 1, rationale: 'Alpha-blockade (phenoxybenzamine or doxazosin) MUST be established first for 10-14 days to control hypertension and allow plasma volume expansion. ONLY THEN is beta-blockade added (to control reflex tachycardia from alpha-blockade). Starting beta-blockade first without alpha-blockade can cause a hypertensive crisis (unopposed alpha stimulation from the tumor while beta-mediated vasodilation is blocked). Volume loading (not restriction) is part of preoperative optimization.' },
  { id: 87, domain: 'IV — Surgical & Special Populations', q: 'Which of the following is the MOST appropriate anesthetic technique for an awake craniotomy for tumor resection near eloquent cortex (speech/motor areas)?', options: ['Deep general anesthesia with remifentanil TIVA', 'Asleep-awake-asleep technique using propofol/dexmedetomidine with regional scalp block', 'Spinal anesthesia at T4 level', 'Ketamine-based TIVA to maintain spontaneous ventilation throughout'], answer: 1, rationale: 'Awake craniotomy uses an "asleep-awake-asleep" or "monitored anesthesia care" approach. A regional scalp block (supraorbital, auriculotemporal, lesser occipital, and greater occipital nerve blocks) provides analgesia for cranial pinning and scalp incision. Propofol ± dexmedetomidine (and low-dose opioid) provides sedation while allowing the patient to be awake and responsive for cortical mapping. Deep GA prevents the awake neurological testing. Ketamine can cause dysphoria, increase ICP, and impair neurological testing.' },
  { id: 88, domain: 'IV — Surgical & Special Populations', q: 'Anaphylaxis during anesthesia is MOST commonly caused by which agent?', options: ['Volatile halogenated anesthetics', 'Neuromuscular blocking agents (NMBAs)', 'Opioids', 'Propofol'], answer: 1, rationale: 'Neuromuscular blocking agents (NMBAs) are the most common cause of anaphylaxis during anesthesia in most countries (particularly succinylcholine and rocuronium). They are IgE-mediated reactions. Volatile anesthetics rarely cause true IgE-mediated anaphylaxis. Opioids can cause mast cell degranulation (anaphylactoid) but true IgE-mediated anaphylaxis to opioids is less common. Propofol can cause anaphylaxis but is less common than NMBA reactions.' },
  { id: 89, domain: 'IV — Surgical & Special Populations', q: 'A patient with FULL STOMACH status requires emergency appendectomy. Which sequence of events BEST describes a modified RSI?', options: ['Pre-oxygenate → administer propofol slowly → insert LMA', 'Pre-oxygenate → induction with propofol + succinylcholine or high-dose rocuronium → cricoid pressure → intubate without mask ventilation', 'Awake fiberoptic intubation with topicalization followed by low-dose midazolam', 'Pre-oxygenate → ketamine → gentle mask ventilation → intubate'], answer: 1, rationale: 'RSI aims to minimize the time between loss of consciousness and definitive airway control (cuffed ETT). Pre-oxygenation maximizes oxygen reserves. IV induction (propofol or thiopental) + rapid-onset paralytic (succinylcholine 1.5 mg/kg or rocuronium 1.2 mg/kg) allows intubating conditions within 45-60 seconds. Mask ventilation is avoided to prevent gastric insufflation. LMA does not protect against aspiration. Awake fiberoptic is for anticipated difficult airway, not standard full-stomach management.' },
  { id: 90, domain: 'IV — Surgical & Special Populations', q: 'The "ex utero intrapartum treatment" (EXIT) procedure is used for which neonatal condition?', options: ['Congenital diaphragmatic hernia repair immediately after delivery', 'Securing a neonate\'s airway for giant neck masses or severe tracheal compression while placental circulation is maintained', 'Emergency C-section for placental abruption', 'In utero fetal cardiac surgery'], answer: 1, rationale: 'The EXIT procedure allows the surgical team to secure the neonate\'s airway (via intubation, tracheostomy, or resection of an obstructing mass) while the baby is partially delivered and placental circulation is maintained, providing time without fetal asphyxia. It is used for giant fetal neck masses (lymphangiomas, teratomas), severe tracheal/bronchial stenosis, and giant lung masses. CDH repair is typically done postnatally after stabilization. Placental abruption is a different obstetric emergency.' },
  { id: 91, domain: 'IV — Surgical & Special Populations', q: 'A patient with a history of previous carotid endarterectomy presents for CABG. During cardiopulmonary bypass, cerebral protection strategies include:', options: ['Mild hyperthermia (39°C) and hypertension', 'Mild hypothermia (32-34°C), adequate MAP (>50-60 mmHg on bypass), and avoidance of hyperglycemia', 'Induced hypertension to 180 mmHg MAP on bypass', 'Deliberate hypocapnia (PaCO2 25 mmHg) to maximize cerebral vasoconstriction'], answer: 1, rationale: 'Cerebral protection on CPB includes: mild hypothermia (reduces CMRO2), maintaining MAP ≥50-60 mmHg on bypass (adequate cerebral perfusion), and tight glucose control (hyperglycemia worsens ischemic injury). pH-stat or alpha-stat acid-base management strategies also play a role. Hyperthermia increases CMRO2 and worsens cerebral ischemia. Extreme hypertension on bypass risks cerebral hyperperfusion and hemorrhage. Deliberate hypocapnia causes cerebral vasoconstriction and is not protective in this context.' },
  { id: 92, domain: 'IV — Surgical & Special Populations', q: 'Which of the following is the MOST important preoperative consideration for a patient with myasthenia gravis (MG) presenting for thymectomy?', options: ['Administer a large dose of succinylcholine to ensure complete paralysis', 'Assess bulbar function and respiratory reserve; use minimal or no NMBAs; have pyridostigmine management plan', 'Discontinue all pyridostigmine 48 hours before surgery', 'Use high-dose corticosteroids on the day of surgery'], answer: 1, rationale: 'MG patients have antibodies against nicotinic ACh receptors, causing variable skeletal muscle weakness. Preoperative assessment of bulbar function (aspiration risk) and respiratory reserve is critical. Patients are exquisitely sensitive to non-depolarizing NMBAs (use minimal doses or none). Succinylcholine should be avoided or used with great caution. Abrupt discontinuation of pyridostigmine can precipitate myasthenic crisis. High-dose steroid administration on the day of surgery can precipitate a transient worsening of MG.' },
  { id: 93, domain: 'IV — Surgical & Special Populations', q: 'An elderly patient (82 years old) with multiple comorbidities is identified as having frailty syndrome. Which anesthetic approach is MOST aligned with enhanced recovery and frailty management principles?', options: ['Maximize sedation to prevent recall in the elderly', 'Multimodal analgesia, minimal opioids, regional techniques, early mobilization, and careful fluid management', 'Use ketamine as the sole agent to avoid opioids', 'Routine preoperative fasting for 12 hours with IV fluid restriction until procedure completion'], answer: 1, rationale: 'Enhanced Recovery After Surgery (ERAS) protocols applied to frail elderly patients emphasize: multimodal analgesia (NSAIDs, acetaminophen, regional blocks) to minimize opioids, goal-directed fluid therapy, minimally invasive techniques when possible, early enteral nutrition, and early mobilization to prevent deconditioning and delirium. Excessive sedation in elderly patients causes delirium, prolonged recovery, and functional decline. Ketamine alone is not sufficient and can cause delirium in elderly patients.' },
  { id: 94, domain: 'IV — Surgical & Special Populations', q: 'Which of the following best describes the anesthetic management during electroconvulsive therapy (ECT)?', options: ['Deep general anesthesia with a volatile agent to prevent awareness', 'Brief ultra-short-acting induction (methohexital or propofol) with succinylcholine to attenuate motor convulsions', 'Conscious sedation with midazolam and fentanyl only', 'Spinal anesthesia to T4 level'], answer: 1, rationale: 'ECT anesthesia requires a brief, ultra-short-acting induction agent (methohexital 0.75-1 mg/kg preferred; propofol is alternative but raises the seizure threshold) and succinylcholine (0.5-1 mg/kg) to modify (attenuate) the motor convulsion and prevent musculoskeletal injury, while still allowing EEG seizure activity to be monitored. Volatile agents are not used for ECT due to their anticonvulsant properties. Conscious sedation alone without paralysis is inadequate to safely modify the convulsion. Spinal anesthesia is not used for ECT.' },
  { id: 95, domain: 'IV — Surgical & Special Populations', q: 'A patient with known sickle cell disease (SCD) is scheduled for an elective cholecystectomy. The MOST important perioperative consideration is:', options: ['Avoid all opioids due to the risk of vaso-occlusive crisis', 'Maintain adequate oxygenation, hydration, and normothermia; avoid hypoxia, acidosis, and dehydration', 'Administer high-dose steroids to prevent sickling', 'Use a tourniquet on the arm for IV access to prevent blood loss'], answer: 1, rationale: 'The primary perioperative concerns in SCD are prevention of the factors that promote sickling: hypoxia (low O2 saturation), acidosis, dehydration, hypothermia, and stasis. Maintaining adequate oxygenation (SpO2 >95%), IV hydration, normothermia, and avoiding vasoconstrictive stimuli are critical. Opioids are appropriate for pain management in SCD; withholding them is inappropriate and potentially harmful. Steroids do not prevent sickling. Tourniquets create stasis, promote hypoxia, and increase the risk of sickling; they should be used cautiously or avoided.' },
  { id: 96, domain: 'IV — Surgical & Special Populations', q: 'Which of the following is the MOST common cause of cardiac arrest in pregnant patients undergoing obstetric anesthesia?', options: ['Tension pneumothorax from mechanical ventilation', 'High spinal anesthesia causing cardiovascular collapse', 'Pulmonary embolism from amniotic fluid embolism', 'Local anesthetic toxicity from epidural top-up'], answer: 1, rationale: 'High spinal anesthesia (total spinal) during obstetric anesthesia — from an inadvertent intrathecal injection of an epidural dose, or an excessively high spinal block — is one of the most common causes of cardiac arrest in obstetrics. It causes complete sympathectomy, bradycardia, cardiovascular collapse, and respiratory arrest. Tension pneumothorax from ventilation is less common in obstetric cases. Amniotic fluid embolism is catastrophic but less common than high spinal. While LAST from epidural top-up is a risk, high spinal is more common overall.' },
  { id: 97, domain: 'IV — Surgical & Special Populations', q: 'A trauma patient presents to the OR with massive hemorrhage. Which of the following describes the current "damage control resuscitation" approach?', options: ['Large-volume crystalloid (NS) infusion at 1:1:1 ratio first, then packed red blood cells', 'Balanced resuscitation with 1:1:1 ratio of packed RBCs:FFP:platelets with permissive hypotension (MAP 50-65 mmHg) until hemorrhage control', 'Aggressive colloid infusion to maintain normal MAP of 80 mmHg', 'Immediate desmopressin and antifibrinolytics as first-line'], answer: 1, rationale: 'Damage control resuscitation (DCR) uses: balanced blood product resuscitation (1:1:1 — PRBCs:FFP:platelets), permissive hypotension (MAP 50-65 mmHg or SBP 80-90 mmHg) until surgical hemorrhage control, early administration of tranexamic acid (within 3 hours of injury), and avoidance of large-volume crystalloids (which dilute clotting factors, worsen coagulopathy, cause acidosis, and edema). Crystalloid-first resuscitation is associated with worse outcomes in massive hemorrhage. TXA and DDAVP are adjuncts, not first-line resuscitation.' },
  { id: 98, domain: 'IV — Surgical & Special Populations', q: 'Which factor places a premature infant (born at 28 weeks, now 36 weeks corrected age) at greatest risk for postoperative apnea after general anesthesia?', options: ['High metabolic rate and large surface-area-to-volume ratio', 'Immature respiratory control centers with decreased response to hypercapnia and hypoxia', 'Relative polycythemia from fetal hemoglobin', 'Increased pulmonary vascular resistance'], answer: 1, rationale: 'Premature infants have immature brainstem respiratory control centers. Combined with the depressant effects of anesthetic agents, this leads to postoperative apnea (cessation of breathing >15-20 seconds or with associated bradycardia/desaturation), which can persist up to 60 weeks postconceptual age. These infants require apnea monitoring for 12-24 hours postoperatively. Caffeine is given to reduce apnea risk. High metabolic rate increases oxygen consumption but is not the primary cause of postoperative apnea.' },
  { id: 99, domain: 'IV — Surgical & Special Populations', q: 'For a patient with severe COPD (FEV1 35% predicted) undergoing lobectomy, which intraoperative strategy best minimizes dynamic hyperinflation?', options: ['High respiratory rate (RR 20-25 bpm) with small tidal volumes', 'Long expiratory time (I:E ratio 1:3 or greater), lower RR, and avoidance of excessive PEEP', 'Apply high PEEP (15 cmH2O) to prevent alveolar collapse', 'Use N2O to reduce FiO2 requirements and improve oxygenation'], answer: 1, rationale: 'In severe COPD, airways collapse during expiration (air trapping), leading to dynamic hyperinflation and intrinsic PEEP (auto-PEEP). Management requires: prolonged expiratory time (I:E ratio ≥1:3), lower respiratory rate, adequate tidal volume (6-8 mL/kg IBW), and permissive hypercapnia if needed. Excessive extrinsic PEEP worsens hyperinflation. High RR with inadequate expiratory time worsens air trapping and auto-PEEP. High PEEP in obstructed airways increases air trapping and risk of pneumothorax. N2O is contraindicated in COPD patients undergoing pulmonary resection.' },
  { id: 100, domain: 'IV — Surgical & Special Populations', q: 'A patient with Type 1 diabetes mellitus (T1DM) presents for elective bowel resection. Which perioperative blood glucose target is MOST appropriate according to current evidence-based guidelines?', options: ['60-80 mg/dL (tight glycemic control)', '140-180 mg/dL', '>200 mg/dL to prevent intraoperative hypoglycemia', '80-110 mg/dL (intensive glycemic control)'], answer: 1, rationale: 'Current Society of Thoracic Surgeons, ADA, and perioperative guidelines recommend a target blood glucose of 140-180 mg/dL for most surgical patients. Tight glycemic control (80-110 mg/dL) was shown in the NICE-SUGAR trial to increase mortality due to episodes of hypoglycemia. 60-80 mg/dL is hypoglycemia and is dangerous perioperatively. Glucose >200 mg/dL is associated with increased infection, poor wound healing, and osmotic diuresis. Intensive control (80-110 mg/dL) increases hypoglycemia risk and mortality as demonstrated by NICE-SUGAR.' },
];

const DOMAIN_COLORS = {
  'I': { bg: 'bg-blue-50', border: 'border-blue-200', badge: 'bg-blue-100 text-blue-700' },
  'II': { bg: 'bg-purple-50', border: 'border-purple-200', badge: 'bg-purple-100 text-purple-700' },
  'III': { bg: 'bg-green-50', border: 'border-green-200', badge: 'bg-green-100 text-green-700' },
  'IV': { bg: 'bg-orange-50', border: 'border-orange-200', badge: 'bg-orange-100 text-orange-700' },
};

function getDomainNum(domain) {
  if (domain.startsWith('I —')) return 'I';
  if (domain.startsWith('II —')) return 'II';
  if (domain.startsWith('III —')) return 'III';
  return 'IV';
}

function ScoreBar({ score, total }) {
  const pct = total > 0 ? Math.round((score / total) * 100) : 0;
  const color = pct >= 85 ? 'bg-emerald-500' : pct >= 75 ? 'bg-teal-500' : pct >= 65 ? 'bg-amber-500' : 'bg-red-500';
  const label = pct >= 85 ? 'Exceptional preparation!' : pct >= 75 ? 'Well-prepared!' : pct >= 65 ? 'Targeted review recommended' : 'Intensive review needed';
  return (
    <div>
      <div className="flex items-center justify-between mb-1">
        <span className="text-sm font-semibold text-foreground">{score}/{total} correct ({pct}%)</span>
        <span className="text-xs text-muted-foreground">{label}</span>
      </div>
      <div className="w-full h-2.5 bg-secondary rounded-full overflow-hidden">
        <div className={`h-full rounded-full transition-all duration-700 ${color}`} style={{ width: `${pct}%` }} />
      </div>
    </div>
  );
}

export default function NCEPracticeTest2() {
  const { isEntitled } = useEntitlement();
  const [paywallOpen, setPaywallOpen] = useState(false);
  const [showGate, setShowGate] = useState(false);
  const [currentQ, setCurrentQ] = useState(0);
  const [selected, setSelected] = useState(null);
  const [showAnswer, setShowAnswer] = useState(false);
  const [answers, setAnswers] = useState({});
  const [mode, setMode] = useState('test');
  const [reviewQ, setReviewQ] = useState(0);
  const [showRationale, setShowRationale] = useState(false);

  const availableQuestions = isEntitled ? QUESTIONS : QUESTIONS.slice(0, FREE_PREVIEW_LIMIT);

  // Scroll to top whenever the question or mode changes so the question is visible
  useScrollReset([currentQ, reviewQ, mode]);

  const q = availableQuestions[currentQ];
  const domNum = getDomainNum(q.domain);
  const colors = DOMAIN_COLORS[domNum];
  const totalAnswered = Object.keys(answers).length;
  const totalCorrect = Object.values(answers).filter(a => a.correct).length;

  function handleSelect(idx) {
    if (showAnswer) return;
    setSelected(idx);
    setShowAnswer(true);
    setAnswers(prev => ({ ...prev, [q.id]: { chosen: idx, correct: idx === q.answer } }));
  }

  function handleNext() {
    setSelected(null);
    setShowAnswer(false);
    if (currentQ < availableQuestions.length - 1) {
      setCurrentQ(currentQ + 1);
    } else if (isEntitled) {
      setMode('results');
    } else {
      setShowGate(true);
    }
  }

  function handleReset() {
    setCurrentQ(0);
    setSelected(null);
    setShowAnswer(false);
    setAnswers({});
    setMode('test');
    setReviewQ(0);
    setShowRationale(false);
    setShowGate(false);
  }

  function getOptionStyle(idx) {
    if (!showAnswer) {
      return selected === idx ? 'bg-primary/10 border-primary ring-1 ring-primary' : 'bg-card border-border hover:bg-secondary/50';
    }
    if (idx === q.answer) return 'bg-emerald-50 border-emerald-300 ring-1 ring-emerald-400';
    if (idx === selected && idx !== q.answer) return 'bg-red-50 border-red-300 ring-1 ring-red-400';
    return 'bg-card border-border opacity-50';
  }

  // RESULTS MODE
  if (mode === 'results') {
    const pct = Math.round((totalCorrect / QUESTIONS.length) * 100);
    const domainStats = { I: { correct: 0, total: 0 }, II: { correct: 0, total: 0 }, III: { correct: 0, total: 0 }, IV: { correct: 0, total: 0 } };
    QUESTIONS.forEach(qn => {
      const d = getDomainNum(qn.domain);
      domainStats[d].total++;
      if (answers[qn.id]?.correct) domainStats[d].correct++;
    });
    return (
      <div className="flex flex-col gap-4">
        <div className="bg-teal-700 text-white rounded-2xl p-5 text-center">
          <Trophy className="w-10 h-10 mx-auto mb-2 opacity-90" />
          <h2 className="font-bold text-xl">Test Complete!</h2>
          <p className="text-4xl font-bold mt-1">{pct}%</p>
          <p className="text-sm opacity-80 mt-1">{totalCorrect} / {QUESTIONS.length} correct</p>
        </div>
        <div className="bg-card rounded-2xl border border-border p-4 space-y-3">
          <h3 className="font-bold text-sm text-foreground">Results by Domain</h3>
          {Object.entries(domainStats).map(([d, stat]) => {
            const dpct = Math.round((stat.correct / stat.total) * 100);
            const colors2 = DOMAIN_COLORS[d];
            return (
              <div key={d} className={`rounded-xl p-3 border ${colors2.bg} ${colors2.border}`}>
                <div className="flex items-center justify-between mb-1">
                  <span className="text-xs font-semibold text-foreground">Domain {d}</span>
                  <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${colors2.badge}`}>{stat.correct}/{stat.total} ({dpct}%)</span>
                </div>
                <div className="w-full h-1.5 bg-card/50 rounded-full overflow-hidden">
                  <div className="h-full bg-current rounded-full transition-all duration-500" style={{ width: `${dpct}%` }} />
                </div>
              </div>
            );
          })}
        </div>
        <div className="bg-amber-50 border border-amber-200 rounded-xl p-3">
          <p className="text-xs text-amber-800 font-medium">Performance targets: Below 65% = intensive review | 65-74% = targeted review | 75%+ = well-prepared | 85%+ = exceptional preparation</p>
        </div>
        <div className="flex gap-2">
          <button onClick={() => { setMode('review'); setReviewQ(0); setShowRationale(false); }}
            className="flex-1 py-3 bg-teal-50 border border-teal-200 rounded-xl text-sm font-semibold text-teal-700 active:scale-95 transition-all">
            📖 Review Answers
          </button>
          <button onClick={handleReset}
            className="flex-1 py-3 bg-primary text-white rounded-xl text-sm font-semibold active:scale-95 transition-all flex items-center justify-center gap-1">
            <RotateCcw className="w-4 h-4" /> Restart Test
          </button>
        </div>
        <p className="text-xs text-muted-foreground text-center">© CE HALO LLC — For educational use only. Not for clinical decision-making.</p>
      </div>
    );
  }

  // REVIEW MODE
  if (mode === 'review') {
    const rq = QUESTIONS[reviewQ];
    const rDomNum = getDomainNum(rq.domain);
    const rColors = DOMAIN_COLORS[rDomNum];
    const userAnswer = answers[rq.id];
    return (
      <div className="flex flex-col gap-3">
        <div className="flex items-center justify-between">
          <button onClick={() => setMode('results')} className="flex items-center gap-1 text-primary text-sm font-medium">
            <ChevronLeft className="w-4 h-4" /> Results
          </button>
          <span className="text-xs text-muted-foreground">Q{reviewQ + 1} of {QUESTIONS.length}</span>
        </div>
        <div className={`rounded-xl p-3 border ${rColors.bg} ${rColors.border}`}>
          <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${rColors.badge}`}>Domain {rDomNum} — {rq.domain.split(' — ')[1]}</span>
          <p className="text-sm font-semibold text-foreground mt-2 leading-relaxed">{rq.q}</p>
        </div>
        <div className="flex flex-col gap-2">
          {rq.options.map((opt, idx) => {
            let style = 'bg-card border-border';
            let icon = null;
            if (idx === rq.answer) { style = 'bg-emerald-50 border-emerald-300'; icon = <CheckCircle2 className="w-4 h-4 text-emerald-500 shrink-0" />; }
            else if (userAnswer?.chosen === idx && idx !== rq.answer) { style = 'bg-red-50 border-red-300'; icon = <XCircle className="w-4 h-4 text-red-500 shrink-0" />; }
            return (
              <div key={idx} className={`flex items-start gap-2 p-3 rounded-xl border ${style}`}>
                <span className="text-xs font-bold text-muted-foreground shrink-0 mt-0.5">{String.fromCharCode(65 + idx)}.</span>
                <p className="text-xs text-foreground flex-1">{opt}</p>
                {icon}
              </div>
            );
          })}
        </div>
        <button onClick={() => setShowRationale(r => !r)}
          className="flex items-center justify-between w-full p-3 bg-teal-50 border border-teal-200 rounded-xl text-sm font-semibold text-teal-700 active:scale-95 transition-all">
          <span>📖 Rationale</span>
          {showRationale ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
        </button>
        {showRationale && (
          <div className="p-3 bg-teal-50/50 border border-teal-200 rounded-xl">
            <p className="text-xs text-foreground leading-relaxed">{rq.rationale}</p>
          </div>
        )}
        <div className="flex gap-2">
          <button onClick={() => { setReviewQ(r => Math.max(0, r - 1)); setShowRationale(false); }}
            disabled={reviewQ === 0}
            className="flex-1 py-3 bg-secondary border border-border rounded-xl text-sm font-semibold text-muted-foreground disabled:opacity-40 active:scale-95 transition-all flex items-center justify-center gap-1">
            <ChevronLeft className="w-4 h-4" /> Prev
          </button>
          <button onClick={() => { setReviewQ(r => Math.min(QUESTIONS.length - 1, r + 1)); setShowRationale(false); }}
            disabled={reviewQ === QUESTIONS.length - 1}
            className="flex-1 py-3 bg-primary text-white rounded-xl text-sm font-semibold disabled:opacity-40 active:scale-95 transition-all flex items-center justify-center gap-1">
            Next <ChevronRight className="w-4 h-4" />
          </button>
        </div>
      </div>
    );
  }

  // FREE PREVIEW GATE
  if (showGate) {
    return (
      <>
        <QuizFreePreviewGate
          answeredCount={FREE_PREVIEW_LIMIT}
          totalQuestions={QUESTIONS.length}
          onSubscribe={() => setPaywallOpen(true)}
          onBack={handleReset}
        />
        <PaywallModal open={paywallOpen} onClose={() => setPaywallOpen(false)} />
      </>
    );
  }

  // TEST MODE
  return (
    <div className="flex flex-col gap-3">
      {/* Header */}
      <div className="bg-teal-700 text-white px-4 py-4 rounded-2xl">
        <div className="flex items-center justify-between mb-2">
          <div className="flex items-center gap-2">
            <BookOpen className="w-5 h-5" />
            <span className="text-xs font-bold uppercase tracking-widest opacity-80">CE HALO LLC</span>
          </div>
          <button onClick={handleReset}
            className="flex items-center gap-1 px-2.5 py-1.5 bg-card/20 hover:bg-card/30 rounded-lg text-xs font-semibold transition-all active:scale-95">
            <RotateCcw className="w-3.5 h-3.5" /> Reset
          </button>
        </div>
        <h2 className="font-bold text-base">NBCRNA NCE Practice Test #2</h2>
        <p className="text-xs opacity-70">100 Board-Style Questions · All Four Domains</p>
      </div>

      {/* Progress */}
      <div className="bg-card rounded-2xl border border-border p-3">
        <div className="flex items-center justify-between mb-2">
          <span className="text-xs font-semibold text-foreground">Question {currentQ + 1} of {availableQuestions.length}</span>
          <span className="text-xs text-muted-foreground">{totalAnswered} answered · {totalCorrect} correct</span>
        </div>
        <ScoreBar score={totalCorrect} total={totalAnswered} />
      </div>

      {/* Domain badge */}
      <div className={`rounded-xl p-3 border ${colors.bg} ${colors.border}`}>
        <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${colors.badge}`}>Domain {domNum} — {q.domain.split(' — ')[1]}</span>
        <p className="text-sm font-semibold text-foreground mt-2 leading-relaxed">{q.q}</p>
      </div>

      {/* Options */}
      <div className="flex flex-col gap-2">
        {q.options.map((opt, idx) => (
          <button key={idx} onClick={() => handleSelect(idx)}
            className={`flex items-start gap-2 p-3 rounded-xl border text-left transition-all active:scale-[0.98] ${getOptionStyle(idx)}`}>
            <span className="text-xs font-bold text-muted-foreground shrink-0 mt-0.5 min-w-[16px]">{String.fromCharCode(65 + idx)}.</span>
            <p className="text-xs text-foreground leading-relaxed">{opt}</p>
            {showAnswer && idx === q.answer && <CheckCircle2 className="w-4 h-4 text-emerald-500 shrink-0 ml-auto" />}
            {showAnswer && idx === selected && idx !== q.answer && <XCircle className="w-4 h-4 text-red-500 shrink-0 ml-auto" />}
          </button>
        ))}
      </div>

      {/* Rationale */}
      {showAnswer && (
        <div className="p-3 bg-teal-50 border border-teal-200 rounded-xl">
          <p className="text-xs font-semibold text-teal-700 mb-1">
            {selected === q.answer ? '✅ Correct!' : '❌ Incorrect'} — Rationale
          </p>
          <p className="text-xs text-foreground leading-relaxed">{q.rationale}</p>
        </div>
      )}

      {/* Navigation */}
      <div className="flex gap-2">
        <button onClick={() => {
          const prevIdx = Math.max(0, currentQ - 1);
          const prevQ = availableQuestions[prevIdx];
          const prevAnswer = answers[prevQ.id];
          setCurrentQ(prevIdx);
          setSelected(prevAnswer?.chosen ?? null);
          setShowAnswer(prevAnswer !== undefined);
        }}
          disabled={currentQ === 0}
          className="px-4 py-3 bg-secondary border border-border rounded-xl text-sm font-semibold text-muted-foreground disabled:opacity-40 active:scale-95 transition-all">
          <ChevronLeft className="w-4 h-4" />
        </button>
        <button onClick={handleNext}
          disabled={!showAnswer}
          className="flex-1 py-3 bg-primary text-white rounded-xl text-sm font-semibold disabled:opacity-40 active:scale-95 transition-all flex items-center justify-center gap-1">
          {currentQ === QUESTIONS.length - 1 ? 'View Results' : 'Next Question'} <ChevronRight className="w-4 h-4" />
        </button>
      </div>

      <p className="text-xs text-muted-foreground text-center">© CE HALO LLC — For educational use only. Not for clinical decision-making.</p>
    </div>
  );
}